package cn.xiaoyanjiu.ff14chat;
import android.app.Activity;import android.content.MutableContextWrapper;import android.view.ViewGroup;import android.webkit.*;import java.util.*;
/** Three bounded in-process website sessions retain DOM, history and scroll without loading a URL. */
final class BrowserPages {
 static final Map<String,ArrayList<BrowserToolbar.Content>> sessions=new HashMap<>();
 static String canonical(String key,String value){try{java.net.URI u=new java.net.URI(value);if(!"https".equalsIgnoreCase(u.getScheme())||u.getUserInfo()!=null)return null;String host=u.getHost(),path=u.getRawPath(),fragment=u.getRawFragment();if(key.equals("wiki")&&!(host!=null&&(host.equals("huijiwiki.com")||host.endsWith(".huijiwiki.com"))&&path.startsWith("/wiki/")))return null;if(key.equals("fishing")&&!"fish.ffmomola.com".equals(host))return null;if(key.equals("risingStones")&&(!"ff14risingstones.web.sdo.com".equals(host)||fragment==null||!fragment.startsWith("/")||fragment.toLowerCase(java.util.Locale.ROOT).matches(".*(login|oauth|callback|authorize).*")))return null;if(fragment!=null)fragment=fragment.split("[?]",2)[0];return "https://"+host+(u.getPort()>0?":"+u.getPort():"")+(path==null||path.isEmpty()?"/":path)+(fragment==null?"":"#"+fragment);}catch(Exception e){return null;}}
 static String startUrl(Activity a,String key,String home){String value=a.getSharedPreferences("browser-pages",0).getString(key,home);String valid=canonical(key,value);return valid==null?home:valid;}
 static void remember(Activity a,String key,String url){String value=canonical(key,url);if(value!=null)a.getSharedPreferences("browser-pages",0).edit().putString(key,value).apply();}
 static ArrayList<BrowserToolbar.Content> take(Activity a,String key){ArrayList<BrowserToolbar.Content> list=sessions.remove(key);if(list==null)return new ArrayList<>();for(BrowserToolbar.Content web:list){((MutableContextWrapper)web.getContext()).setBaseContext(a);web.onResume();}return list;}
 static void park(Activity a,String key,Collection<? extends WebView> pages){ArrayList<BrowserToolbar.Content> list=new ArrayList<>();for(WebView raw:pages){BrowserToolbar.Content web=(BrowserToolbar.Content)raw;remember(a,key,web.getUrl());if(web.getParent() instanceof ViewGroup)((ViewGroup)web.getParent()).removeView(web);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient());web.onPause();((MutableContextWrapper)web.getContext()).setBaseContext(a.getApplicationContext());list.add(web);}ArrayList<BrowserToolbar.Content> old=sessions.put(key,list);if(old!=null)for(WebView web:old)web.destroy();}
}
